//! Raw FFI bindings to the PICam C API, generated by `bindgen` from the SDK
//! headers with `cargo run -p xtask -- generate`. Not part of this crate's
//! public API.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
